import { Router } from "express";
import validate from "../../shared/middleware/validate.js";
import upload from "../../shared/utils/upload.js";
import { getAddons, createAddon, updateAddon, deleteAddon, } from "./addon.controller.js";
import { addonIdParamsSchema, createAddonBodySchema, updateAddonBodySchema, } from "./addon.validator.js";
const router = Router();
router.get("/", getAddons);
router.post("/", upload.single("image"), validate(createAddonBodySchema, "body"), createAddon);
router.patch("/:id", upload.single("image"), validate(addonIdParamsSchema, "params"), validate(updateAddonBodySchema, "body"), updateAddon);
router.delete("/:id", validate(addonIdParamsSchema, "params"), deleteAddon);
export default router;
